create table c(x text);
insert into c values('apple'),('Banana'),('cherry'),('é'),('ab'),('b'),('日本');
select x from c order by x collate rev;
select x from c order by x collate len16;
select x from c order by x collate lenbe;
select x from c order by x collate nocase;
select x from c order by x collate lazy;
select x from c order by x collate nosuch;
create index ci on c(x collate rev);
select x from c where x > 'b' collate rev order by x collate rev;
pragma integrity_check;
select x from c where x = 'APPLE' collate nocase;
pragma collation_list;
create table d(y text collate len16);
insert into d select x from c;
select y from d order by y;
select y, y < 'ab' from d order by rowid;
create index di on d(y);
select y from d where y between 'ab' and 'zzz' order by y;
select max(y), min(y) from d;
select group_concat(y) over (order by y) from d;
